function translateUI(){
  const ar=state.lang==='ar';
  document.documentElement.lang=ar?'ar':'en';
  document.documentElement.dir=ar?'rtl':'ltr';
  if(!ar)return;
  const walker=document.createTreeWalker(app,NodeFilter.SHOW_TEXT);
  const nodes=[];
  while(walker.nextNode())nodes.push(walker.currentNode);
  for(const n of nodes){
    const raw=n.nodeValue, v=raw.trim();
    if(!v)continue;
    if(translations[v]) n.nodeValue=raw.replace(v,translations[v]);
  }
  app.querySelectorAll('input,textarea,select,[aria-label],[title]').forEach(el=>{
    ['placeholder','aria-label','title'].forEach(attr=>{
      const v=el.getAttribute(attr);
      if(v&&translations[v])el.setAttribute(attr,translations[v]);
    });
  });
}

async function api(path,opts={}){const r=await fetch(path,{credentials:'same-origin',headers:{'content-type':'application/json',...(opts.headers||{})},...opts});let d=null;try{d=await r.json()}catch{}if(!r.ok)throw new Error(d?.error||'Request failed');return d}
function fmtDate(v){return v?new Date(v.replace(' ','T')+'Z').toLocaleString():''}
function fmtSchedule(v){return v?new Date(v).toLocaleString([], {dateStyle:'medium',timeStyle:'short'}):'Immediately'}
function localInputValue(v){if(!v)return '';const d=new Date(v);if(Number.isNaN(d.getTime()))return '';const p=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}T${p(d.getHours())}:${p(d.getMinutes())}`}
function scheduleState(e){const now=Date.now(),start=e.available_from?Date.parse(e.available_from):NaN,end=e.expires_at?Date.parse(e.expires_at):NaN;if(Number.isFinite(end)&&now>=end)return 'expired';if(Number.isFinite(start)&&now<start)return 'scheduled';return 'open'}
function layout(content,opts={}){const adminPortal=isAdminPortal();const ar=state.lang==='ar';const auth=adminPortal?(state.me?.admin?`<button class="btn" onclick="logout()">${ar?'تسجيل الخروج':'Logout'}</button>`:''):state.me?.user?`<button class="btn ghost" onclick="go('dashboard')">${ar?'لوحة الطالب':'Student Dashboard'}</button><button class="btn" onclick="logout()">${ar?'تسجيل الخروج':'Logout'}</button>`:`<button class="btn orange" onclick="go('login')">${ar?'دخول الطالب':'Student Login'}</button>`;return `<div class="shell"><header class="topbar"><a class="brand" href="#" onclick="go('home');return false" aria-label="English Learning Platform"><div class="brand-mark" aria-hidden="true">EL</div><div class="brand-name">${ar?'منصة تعلم الإنجليزية':'English Learning'}<small>${ar?'تعلّم · تطوّر · حقّق':'Learn · Improve · Achieve'}</small></div></a><div class="top-actions"><button class="circle-btn" onclick="toggleLang()" aria-label="Language">${ar?'EN':'AR'}</button><button class="circle-btn theme-btn" onclick="toggleTheme()" aria-label="Theme">${state.theme==='dark'?'☼':'✦'}</button>${auth}</div></header>${content}<footer class="footer">${ar?'منصة تعلم الإنجليزية · تعلّم، تطوّر، حقّق':'English Learning Platform · Learn, Improve, Achieve'}</footer></div>`}
async function boot(){applyTheme();try{state.me=await api('/api/auth/me')}catch{}const adminPortal=isAdminPortal();if(adminPortal)state.view=state.me?.admin?'admin':'admin-login';else state.view=state.me?.user?'dashboard':'home';render()}
function render(){const adminPortal=isAdminPortal();if(adminPortal){if(state.view==='admin'&&state.me?.admin)return renderAdmin();return renderAdminLogin()}if(state.view==='admin-login'||state.view==='admin')state.view='home';if(state.me?.user&&state.view==='home')state.view='dashboard';if(state.view==='login')return renderLogin();if(state.view==='register')return renderRegister();if(state.view==='dashboard'&&state.me?.user)return renderDashboard();if(state.view==='exam'&&state.me?.user)return renderExam();if(state.view==='result')return renderResult(state.lastResult);state.view='home';renderHome()}
function renderHome(){app.innerHTML=layout(`<main class="home-page public-home"><section class="public-hero"><div class="public-copy"><div class="eyebrow">English Learning Platform</div><h1>Better English.<br><span>Clearer progress.</span></h1><p>A modern learning and assessment experience designed by Mr. Mohamed to help students practice, measure progress, and know exactly where they need to improve.</p><div class="public-actions"><button class="btn orange" onclick="go('login')">Student Login ↗</button><div class="trusted-note"><b>No student registration</b><span>Your teacher creates and manages your account.</span></div></div></div><div class="public-teacher"><img src="/teacher.png" alt="Mr. Mohamed, English Teacher"><div><small>YOUR ENGLISH TEACHER</small><b>Mr. Mohamed</b><span>Preparatory & Secondary · General & Azhar</span></div></div></section><section class="public-benefits"><div class="eyebrow">Built for better outcomes</div><h2>More than an online exam.</h2><div class="feature-grid"><div class="feature-card"><span class="feature-icon blue">🎯</span><div><b>Skill-based learning</b><small>Every question can be linked to Vocabulary, Grammar, Reading, Writing, Listening and more.</small></div></div><div class="feature-card"><span class="feature-icon purple">📊</span><div><b>Detailed performance reports</b><small>Students and parents can understand the result instead of seeing one score only.</small></div></div><div class="feature-card"><span class="feature-icon green">📈</span><div><b>Progress over time</b><small>Track improvement from one assessment to the next and celebrate real progress.</small></div></div><div class="feature-card"><span class="feature-icon yellow">💡</span><div><b>Weakness detection</b><small>Identify the skills and topics that need more practice.</small></div></div><div class="feature-card"><span class="feature-icon cyan">📚</span><div><b>Comfortable reading</b><small>Long reading passages are built into the exam and optimized for phones.</small></div></div><div class="feature-card"><span class="feature-icon rose">🔐</span><div><b>Teacher-controlled accounts</b><small>No public registration; student access is created and managed by the teacher.</small></div></div></div></section></main>`)}
function renderAdminLogin(){app.innerHTML=layout(`<main class="page"><div class="center"><div class="card"><div class="eyebrow">Administration</div><h1>Control center.</h1><p class="muted">Authorized administrators only.</p><form class="form" onsubmit="adminLogin(event)"><div class="field"><label>Username</label><input name="username" required autocomplete="username"></div><div class="field"><label>Password</label><input name="password" type="password" required autocomplete="current-password"></div><button class="btn orange">Admin Login</button></form><p class="small-text muted">Student? <span class="link" onclick="go('login')">Student login</span></p></div></div></main>`)}
async function adminLogin(e){e.preventDefault();const f=new FormData(e.target);try{await api('/api/admin/login',{method:'POST',body:JSON.stringify(Object.fromEntries(f))});state.me=await api('/api/auth/me');state.view='admin';render()}catch(x){showToast(x.message)}}
function renderLogin(){app.innerHTML=layout(`<main class="student-access page"><div class="access-wrap"><div class="access-brand"><div class="eyebrow">Student portal</div><h1>Welcome to your English journey.</h1><p class="muted">Your teacher creates your account for you. Just enter the Student ID and password you received.</p></div><div class="card access-card"><div class="access-icon">✓</div><div class="eyebrow">Secure student access</div><h2>Sign in to continue</h2><p class="muted">No registration. No complicated setup.</p><form class="form" onsubmit="studentLogin(event)"><div class="field"><label>Student ID</label><input name="identifier" required autocomplete="username" placeholder="e.g. STU-ABC12345"></div><div class="field"><label>Password</label><input name="password" type="password" required autocomplete="current-password" placeholder="Your password"></div><button class="btn orange" style="width:100%">Enter My Dashboard ↗</button></form><div class="access-note"><b>Your teacher manages your account.</b><span>If you forget your password, ask your teacher to reset it.</span></div></div></div></main>`)}
async function studentLogin(e){e.preventDefault();const f=new FormData(e.target);try{await api('/api/auth/login',{method:'POST',body:JSON.stringify(Object.fromEntries(f))});state.me=await api('/api/auth/me');showToast('Login successful');go('dashboard')}catch(x){showToast(x.message)}}
async function studentRegister(e){e.preventDefault();const f=new FormData(e.target);try{const d=await api('/api/auth/register',{method:'POST',body:JSON.stringify(Object.fromEntries(f))});state.me=await api('/api/auth/me');app.innerHTML=layout(`<main class="page"><div class="center"><div class="card result-box"><div class="eyebrow">Registration complete</div><h2>Your Student ID</h2><div class="score">${esc(d.studentId)}</div><p class="muted">Save this ID. You can use it or your email to log in.</p><button class="btn orange" onclick="go('dashboard')">Continue to Dashboard</button></div></div></main>`)}catch(x){showToast(x.message)}}
async function logout(){await api('/api/auth/logout',{method:'POST'}).catch(()=>{});state.me=null;state.view=(isAdminPortal())?'admin-login':'home';render()}
async function renderDashboard(){let exams=[],results=[];try{[exams,results]=await Promise.all([api('/api/exams'),api('/api/results')])}catch(x){showToast(x.message)}const passed=results.filter(r=>r.passed).length;const avg=results.length?results.reduce((a,r)=>a+Number(r.percentage||0),0)/results.length:0;const best=results.length?Math.max(...results.map(r=>Number(r.percentage||0))):0;app.innerHTML=layout(`<main class="student-home page"><section class="student-welcome"><div class="welcome-copy"><div class="eyebrow">Student dashboard</div><h1>Hi, ${esc(state.me.user.fullName)} 👋</h1><p>Your learning journey is measurable. Take your assigned exams, understand your strengths, and know exactly what to practice next.</p><div class="student-meta"><span>${esc(state.me.user.grade||'Student')}</span><span>${state.me.user.educationSystem==='azhar'?'Azhar':'General'}</span>${state.me.user.groupId?'<span>Group assigned</span>':''}</div></div><div class="teacher-hero"><img src="/teacher.png" alt="English Teacher"><div class="teacher-overlay"><small>YOUR TEACHER</small><b>Mr. Mohamed</b><span>English Teacher</span></div></div></section><section class="parent-value"><div><div class="eyebrow">Why this platform?</div><h2>Not just an exam — a clear learning path.</h2><p>Every answer becomes useful feedback, so the student and parent can see where improvement is needed instead of looking at a score alone.</p></div><div class="value-points"><div><b>🎯 Skill-based assessment</b><span>Vocabulary, Grammar, Reading, Writing, Listening & more.</span></div><div><b>📈 Real progress</b><span>Track improvement across exams, not just one result.</span></div><div><b>💡 Smart feedback</b><span>See strengths, weaknesses and what to practice next.</span></div></div></section><section class="feature-grid"><button class="feature-card" onclick="go('dashboard')"><span class="feature-icon blue">📝</span><div><b>Available Exams</b><small>Assigned assessments with clear timing and instructions.</small></div><span>›</span></button><button class="feature-card" onclick="go('results')"><span class="feature-icon purple">📊</span><div><b>My Results</b><small>Detailed scores and performance history.</small></div><span>›</span></button><div class="feature-card"><span class="feature-icon green">🎯</span><div><b>Skill Analysis</b><small>Know your strongest and weakest English skills.</small></div></div><div class="feature-card"><span class="feature-icon yellow">📚</span><div><b>Reading Practice</b><small>Long passages are displayed comfortably on mobile.</small></div></div><div class="feature-card"><span class="feature-icon cyan">🧭</span><div><b>Personal Progress</b><small>See whether your performance is improving over time.</small></div></div><div class="feature-card"><span class="feature-icon rose">💬</span><div><b>Teacher Support</b><small>Your account and access are managed directly by your teacher.</small></div></div></section><section class="student-stats"><div class="card student-stat"><span>Exams completed</span><b>${results.length}</b><small>${passed} passed</small></div><div class="card student-stat"><span>Average score</span><b>${avg.toFixed(0)}%</b><small>Across completed exams</small></div><div class="card student-stat"><span>Best score</span><b>${best.toFixed(0)}%</b><small>Your current peak</small></div><div class="card student-stat"><span>Next step</span><b>${exams.length?'Exam':'Practice'}</b><small>${exams.length?'You have an exam ready':'Keep building your skills'}</small></div></section><section class="section-head dashboard-section-head"><div><div class="eyebrow">Your assessments</div><h2>Ready when you are</h2></div></section><section class="grid grid-3 student-exams">${exams.length?exams.map(examCard).join(''):`<div class="card empty">No active exams are available right now. Your teacher will add them here.</div>`}</section></main>`)}
function examCard(e){const state=scheduleState(e);const scheduled=state==='scheduled';const schedule=scheduled?`<div class="exam-schedule scheduled"><b>Starts ${esc(fmtSchedule(e.available_from))}</b><span>Available for ${e.available_from&&e.expires_at?Math.max(1,Math.round((Date.parse(e.expires_at)-Date.parse(e.available_from))/3600000))+' hours':'a limited window'}</span></div>`:`<div class="exam-schedule"><b>Available now</b>${e.expires_at?`<span>Until ${esc(fmtSchedule(e.expires_at))}</span>`:'<span>No expiry set</span>'}</div>`;return `<article class="card exam-card ${scheduled?'is-scheduled':''}"><div class="exam-card-top"><span class="pill ${e.status==='active'?'active':''}">${scheduled?'Scheduled':e.status}</span>${Number(e.desktop_required)===1?'<span class="device-badge">Desktop required</span>':''}</div><h3>${esc(e.title)}</h3><p class="muted">${esc(e.description||'English assessment')}</p><div class="exam-meta"><span>${e.question_count} questions</span><span>·</span><span>${e.duration_minutes} min</span><span>·</span><span>Pass ${e.passing_percentage}%</span></div>${schedule}<button class="btn ${scheduled?'ghost':'orange'}" ${scheduled?'disabled':''} onclick="startExam(${e.id})">${scheduled?'Not open yet':'Start Exam ↗'}</button></article>`}
async function startExam(id){
  try{
    clearInterval(state.timer);
    state.submitting=false;
    state.expired=false;
    state.answers={};
    state.questions=[];
    state.currentQuestion=0;
    state.reviewMode=false;
    state.skippedQuestions=[];
    const d=await api(`/api/exams/${id}/start`);
    if(!d?.exam) throw new Error('Exam data could not be loaded');
    if(!Array.isArray(d.questions)) throw new Error('Exam questions could not be loaded');
    if(!d.attemptId) throw new Error('Exam attempt could not be created');
    state.exam=d.exam;
    state.questions=d.questions;
    state.attemptId=d.attemptId;
    state.startedAt=d.startedAt;
    state.view='exam';
    renderExam();
    startTimer();
  }catch(x){
    console.error('START EXAM ERROR:',x);
    if(x.message==='لا يمكن دخول الامتحان مرة أخرى لأنك اجتزت هذا الامتحان بالفعل.')showToast('لا يمكن دخول الامتحان مرة أخرى — لقد اجتزت هذا الامتحان بالفعل.');
    else if(x.message==='This assessment must be taken on a desktop or laptop.')showToast('This assessment must be taken on a desktop or laptop.');
    else if(x.message==='This assessment is not open yet.')showToast('This assessment is not open yet. Check the scheduled start time.');
    else if(x.message==='This assessment is no longer available.')showToast('This assessment is no longer available.');
    else showToast(x.message||'Unable to start exam');
  }
}
function examAnsweredCount(){return state.questions.filter(q=>state.answers[q.id]).length}
function examUnanswered(){return state.questions.map((q,i)=>({q,i})).filter(x=>!state.answers[x.q.id])}
function answerQuestion(questionId,answer){state.answers[questionId]=answer;state.skippedQuestions=state.skippedQuestions.filter(i=>state.questions[i]?.id!==questionId);renderExam()}
function nextQuestion(){
  const q=state.questions[state.currentQuestion];
  if(q&&!state.answers[q.id])state.skippedQuestions=[...new Set([...state.skippedQuestions,state.currentQuestion])];
  if(state.currentQuestion<state.questions.length-1){state.currentQuestion++;renderExam();return}
  state.reviewMode=true;renderExam();
}
function previousQuestion(){if(state.currentQuestion>0){state.currentQuestion--;state.reviewMode=false;renderExam()}}
function jumpToQuestion(index){if(index<0||index>=state.questions.length)return;state.currentQuestion=index;state.reviewMode=false;renderExam()}
function renderExam(){
  if(Number(state.exam?.desktop_required)===1 && /Mobi|Android|iPhone|iPad|iPod|Windows Phone/i.test(navigator.userAgent||'')){showDesktopRequiredModal();return}
  const total=state.questions.length, answered=examAnsweredCount(), unanswered=examUnanswered();
  if(!total){app.innerHTML=layout(`<main class="page"><div class="center"><div class="card empty">No questions are available for this assessment.</div></div></main>`);return}
  if(state.reviewMode){
    const missing=unanswered;
    app.innerHTML=layout(`<main class="page"><div class="center"><div class="exam-top"><div><div class="eyebrow">Active assessment</div><b>${esc(state.exam.title)}</b></div><div class="timer" id="timer">--:--</div></div><section class="exam-review card"><div class="eyebrow">Final review</div><h1>Review your answers.</h1><p class="muted">You must answer every question before you can submit this assessment.</p><div class="review-stats"><div><b>${answered}</b><span>Answered</span></div><div><b>${total-answered}</b><span>Remaining</span></div></div>${missing.length?`<div class="review-warning"><b>${missing.length} question${missing.length===1?'':'s'} still need an answer.</b><span>Return to each question below before submitting.</span></div>`:`<div class="review-ready"><b>All questions are answered.</b><span>You can submit your assessment now.</span></div>`}<div class="review-question-list">${state.questions.map((q,i)=>{const done=!!state.answers[q.id];return `<button type="button" class="review-question ${done?'is-answered':'is-missing'}" onclick="jumpToQuestion(${i})"><span>Q${i+1}</span><strong>${done?'Answered':'Needs answer'}</strong><em>${done?'✓':'!'}</em></button>`}).join('')}</div><div class="actions exam-actions"><button type="button" class="btn ghost" onclick="jumpToQuestion(${missing.length?missing[0].i:total-1})">${missing.length?'Return to unanswered':'Review last question'}</button><button type="button" class="btn orange" ${missing.length?'disabled':''} onclick="submitExam()">Submit Exam</button><button type="button" class="btn ghost" onclick="if(confirm('Leave the exam? Your in-progress attempt will remain until its timer expires.'))go('dashboard')">Leave</button></div></section></div></main>`);
    return;
  }
  const i=Math.max(0,Math.min(total-1,state.currentQuestion));state.currentQuestion=i;const q=state.questions[i];const filesHtml='';
  const progress=total?((i+1)/total)*100:0;
  app.innerHTML=layout(`<main class="page"><div class="center"><div class="exam-top"><div><div class="eyebrow">Active assessment</div><b>${esc(state.exam.title)}</b></div><div class="timer" id="timer">--:--</div></div><section class="exam-progress card"><div><span>Question ${i+1} of ${total}</span><b>${answered} / ${total} answered</b></div><div class="progress-track"><span style="width:${progress}%"></span></div></section><section class="question exam-question"><div class="small-text muted">Question ${i+1} · ${q.points} point${q.points==1?'':'s'}</div><div class="question-title">${esc(q.question_text)}</div>${filesHtml}<div class="options">${['A','B','C','D'].map(k=>`<label class="option"><input type="radio" name="currentQuestion" value="${k}" ${state.answers[q.id]===k?'checked':''} onchange="answerQuestion(${q.id},'${k}')"> <b>${k}.</b> <span>${esc(q['option_'+k.toLowerCase()])}</span></label>`).join('')}</div></section><div class="exam-navigation"><button type="button" class="btn ghost" onclick="previousQuestion()" ${i===0?'disabled':''}>Previous</button><div class="exam-nav-center"><span>${state.answers[q.id]?'Answered':'Not answered'}</span>${!state.answers[q.id]?'<small>You can skip this question and return to it during final review.</small>':''}</div><button type="button" class="btn orange" onclick="nextQuestion()">${!state.answers[q.id]?(i===total-1?'Skip & Review':'Skip & Next'):(i===total-1?'Review & Submit':'Next Question')}</button></div><div class="exam-footer-actions"><button type="button" class="btn ghost" onclick="state.reviewMode=true;renderExam()">Review answers (${answered}/${total})</button><button type="button" class="btn ghost" onclick="if(confirm('Leave the exam? Your in-progress attempt will remain until its timer expires.'))go('dashboard')">Leave</button></div></div></main>`);
}
function showDesktopRequiredModal(){openModal(`<div class="device-warning"><div class="device-warning-icon"><span>▣</span></div><div class="eyebrow">Device requirement</div><h2>Desktop or laptop required</h2><p class="muted">This assessment contains case-study material that is designed for a larger screen. You cannot start it from a phone or tablet.</p><div class="device-warning-points"><span><b>01</b> Better case-study visibility</span><span><b>02</b> Easier document and spreadsheet review</span><span><b>03</b> More comfortable answer navigation</span></div><div class="device-warning-note">Please open this assessment from a desktop or laptop to continue.</div><div class="actions"><button class="btn orange" onclick="closeModal();go('dashboard')">Back to Dashboard</button></div></div>`)}
function startTimer(){
  clearInterval(state.timer);
  if(!state.exam||!state.startedAt){
    console.error('Timer data missing',state.exam,state.startedAt);
    return;
  }
  const raw=String(state.startedAt);
  const normalized=raw.includes('T')?raw:raw.replace(' ','T');
  const parsed=Date.parse(normalized.endsWith('Z')?normalized:`${normalized}Z`);
  const duration=Number(state.exam.duration_minutes);
  if(!Number.isFinite(parsed)||!Number.isFinite(duration)||duration<=0){
    console.error('Invalid timer values:',state.startedAt,state.exam.duration_minutes);
    const el=document.getElementById('timer');
    if(el)el.textContent='--:--';
    return;
  }
  const end=parsed+(duration*60000);
  const tick=()=>{
    if(state.view!=='exam'){
      clearInterval(state.timer);
      return;
    }
    const left=Math.max(0,end-Date.now());
    const minutes=Math.floor(left/60000);
    const seconds=Math.floor(left/1000)%60;
    const el=document.getElementById('timer');
    if(el)el.textContent=`${String(minutes).padStart(2,'0')}:${String(seconds).padStart(2,'0')}`;
    if(left<=0&&!state.submitting){
      clearInterval(state.timer);
      state.expired=true;
      submitExam(null,true);
    }
  };
  tick();
  state.timer=setInterval(tick,1000);
}
async function submitExam(e,expired=false){
  if(e) e.preventDefault();
  if(state.submitting) return;
  if(!state.attemptId){showToast('Exam attempt is missing');return}
  const unanswered=examUnanswered();
  if(!expired&&unanswered.length){
    state.reviewMode=true;state.currentQuestion=unanswered[0].i;renderExam();showToast(`Please answer all ${unanswered.length} remaining question${unanswered.length===1?'':'s'} before submitting.`);return;
  }
  if(!expired&&!confirm('Submit this exam now?')) return;
  state.submitting=true;clearInterval(state.timer);
  const answers=Object.entries(state.answers).map(([questionId,answer])=>({questionId:Number(questionId),answer}));
  try{
    const d=await api(`/api/attempts/${state.attemptId}/submit`,{method:'POST',body:JSON.stringify({answers,expired})});
    if(!d?.result) throw new Error('The exam was submitted but no result was returned');
    state.lastResult=d.result;state.view='result';renderResult(d.result);
  }catch(x){
    console.error('SUBMIT EXAM ERROR:',x);state.submitting=false;showToast(x.message||'Unable to submit the exam');
    if(state.view==='exam')renderExam();
  }
}
function renderResult(r){const pct=Math.max(0,Math.min(100,Number(r.percentage)||0));const ar=state.lang==='ar';const passed=!!r.passed;const statusText=passed?(ar?'ناجح':'Passed'):(ar?'لم ينجح':'Not passed');const message=passed?(ar?'لقد اجتزت هذا الامتحان بنجاح.':'Great work — you passed this assessment.'):(ar?'لم تصل إلى درجة النجاح هذه المرة. استمر في التدريب وحاول مرة أخرى.':'This result shows exactly where more practice can help you improve.');const skills=Array.isArray(r.skillBreakdown)?r.skillBreakdown:[];const weak=skills.filter(x=>Number(x.percentage)<70).sort((a,b)=>a.percentage-b.percentage);app.innerHTML=layout(`<main class="page result-page"><div class="result-shell"><div class="result-header"><div><div class="eyebrow">${ar?'اكتمل الامتحان':'Assessment complete'}</div><h1>${esc(r.examTitle)}</h1><p class="muted">${ar?'النتيجة النهائية':'Overall performance'} · ${fmtDate(r.submittedAt||new Date().toISOString())}</p></div><span class="result-status ${passed?'is-pass':'is-fail'}"><span class="status-dot"></span>${statusText}</span></div><section class="result-hero card"><div class="score-ring" style="--score:${pct}%"><div class="score-ring-inner"><strong>${pct.toFixed(1)}%</strong><span>Score</span></div></div><div class="result-summary"><div class="eyebrow">Your progress</div><h2>${message}</h2><p class="muted">The platform breaks the exam down by English skill, so the score becomes a useful learning report.</p></div></section><section class="result-metrics"><div class="result-metric card"><span>Points earned</span><strong>${r.score} <small>/ ${r.totalPoints}</small></strong></div><div class="result-metric card"><span>Pass mark</span><strong>${Number(r.passingPercentage??0).toFixed(0)}%</strong></div><div class="result-metric card"><span>Questions answered</span><strong>${r.answeredCount??'—'} <small>/ ${r.questionCount??'—'}</small></strong></div></section><section class="card result-skills"><div class="eyebrow">Skill report</div><h2>What are you good at — and what needs practice?</h2>${skills.length?`<div class="skill-report-grid">${skills.map(x=>`<div class="skill-report"><div><b>${esc(x.skill)}</b><small>${x.questions} questions</small></div><strong>${Number(x.percentage||0).toFixed(0)}%</strong><div class="skill-bar"><span style="width:${Math.max(0,Math.min(100,Number(x.percentage)||0))}%"></span></div></div>`).join('')}</div>${weak.length?`<div class="weakness-box"><b>🎯 Priority for improvement</b><span>${weak.slice(0,2).map(x=>esc(x.skill)).join(' · ')}</span><small>Focus on these skills in your next practice session.</small></div>`:`<div class="strength-box"><b>🌟 Strong performance across your skills</b><span>Keep practicing to maintain this level.</span></div>`}`:`<div class="empty">Skill analysis will appear when your teacher tags exam questions by skill.</div>`}</section><div class="result-actions">${!passed&&r.examId?`<button class="btn orange" onclick="startExam(${Number(r.examId)})">Retake Exam ↗</button>`:''}<button class="btn ghost" onclick="go('dashboard')">Back to Dashboard ↗</button></div></div></main>`);if(state.lang==='ar')translateUI();}

async function renderAdmin(){app.innerHTML=layout(`<div class="admin-layout"><aside class="sidebar"><button class="side-btn ${state.adminTab==='overview'?'active':''}" onclick="adminTab('overview')">Overview</button><button class="side-btn ${state.adminTab==='students'?'active':''}" onclick="adminTab('students')">Students</button><button class="side-btn ${state.adminTab==='exams'?'active':''}" onclick="adminTab('exams')">Exams</button><button class="side-btn ${state.adminTab==='results'?'active':''}" onclick="adminTab('results')">Results</button><button class="side-btn ${state.adminTab==='groups'?'active':''}" onclick="adminTab('groups')">Groups</button><button class="side-btn ${state.adminTab==='analytics'?'active':''}" onclick="adminTab('analytics')">Analytics</button>${state.me.admin.role==='super_admin'?`<button class="side-btn ${state.adminTab==='admins'?'active':''}" onclick="adminTab('admins')">Admin Users</button>`:''}</aside><main class="admin-main" id="admin-main"></main></div>`);await loadAdminTab()}
function adminTab(t){state.adminTab=t;renderAdmin()}
async function loadAdminTab(){const el=document.getElementById('admin-main');if(state.adminTab==='overview')return adminOverview(el);if(state.adminTab==='students')return adminStudents(el);if(state.adminTab==='exams')return adminExams(el);if(state.adminTab==='results')return adminResults(el);if(state.adminTab==='groups')return adminGroups(el);if(state.adminTab==='analytics')return adminAnalytics(el);if(state.adminTab==='admins')return adminAdmins(el)}
