async function saveGroup(e){e.preventDefault();try{await api('/api/admin/groups',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();showToast('Group created');adminTab('groups')}catch(x){showToast(x.message)}}
async function adminAnalytics(el){const d=await api('/api/admin/analytics');const weakest=d.skills?.[0];el.innerHTML=`<div class="dashboard-head"><div><div class="eyebrow">Teaching insights</div><h1>Analytics</h1><p class="muted">See which skills need attention across all students.</p></div></div><div class="card insight-banner"><div class="insight-icon">🎯</div><div><b>${weakest?`Priority skill: ${esc(weakest.skill)}`:'No skill data yet'}</b><p>${weakest?`Students currently average ${Number(weakest.percentage||0).toFixed(1)}% in this skill. Consider assigning targeted practice.`:'Once students complete skill-tagged questions, the platform will identify the weakest area automatically.'}</p></div></div><div class="section-head"><div><div class="eyebrow">Skill performance</div><h2>Where students need support</h2></div></div><div class="grid grid-2">${(d.skills||[]).map(x=>`<div class="card analytics-row"><div><b>${esc(x.skill)}</b><small>${x.students||0} students</small></div><strong>${Number(x.percentage||0).toFixed(1)}%</strong></div>`).join('')||'<div class="card empty">No analytics data yet.</div>'}</div><div class="section-head"><div><div class="eyebrow">Class overview</div><h2>Groups</h2></div></div><div class="grid grid-3">${(d.groups||[]).map(g=>`<div class="card"><b>${esc(g.name)}</b><p class="muted">${esc(g.grade)} · ${g.system==='azhar'?'Azhar':'General'}</p><div class="statline"><span>Students</span><span>${g.students}</span></div><div class="statline"><span>Average</span><span>${g.average_score==null?'—':Number(g.average_score).toFixed(1)+'%'}</span></div></div>`).join('')||'<div class="card empty">Create groups to see class analytics.</div>'}</div>`}
async function resetStudentPassword(id,name){openModal(`<div class="modal-head"><div><div class="eyebrow">Account security</div><h2>Change student password</h2><p class="muted">Set a new password for ${esc(name)}. The student will need to sign in again.</p></div><button class="icon-btn" onclick="closeModal()">×</button></div><form class="form" onsubmit="saveStudentPassword(event,${id})"><div class="field"><label>New password</label><input name="newPassword" type="password" minlength="8" maxlength="128" autocomplete="new-password" required placeholder="At least 8 characters"></div><div class="field"><label>Confirm password</label><input name="confirmPassword" type="password" minlength="8" maxlength="128" autocomplete="new-password" required placeholder="Repeat the new password"></div><div class="card security-note"><b>Admin action</b><span>The student's existing sessions will be signed out after the password is changed.</span></div><div class="actions"><button type="button" class="btn ghost" onclick="studentDetail(${id})">Cancel</button><button class="btn orange">Update password</button></div></form>`)}
async function saveStudentPassword(e,id){e.preventDefault();const fd=new FormData(e.target),newPassword=String(fd.get('newPassword')||''),confirmPassword=String(fd.get('confirmPassword')||'');if(newPassword!==confirmPassword){showToast('Passwords do not match');return}try{await api(`/api/admin/students/${id}/reset-password`,{method:'POST',body:JSON.stringify({newPassword})});closeModal();showToast('Student password updated');studentDetail(id)}catch(x){showToast(x.message||'Unable to update password')}}
async function toggleStudent(id,status){await api(`/api/admin/students/${id}`,{method:'PATCH',body:JSON.stringify({status})});closeModal();showToast('Student status updated');adminTab('students')}
async function adminExams(el){const rows=await api('/api/admin/exams');el.innerHTML=`<div class="dashboard-head"><div><div class="eyebrow">Assessment design</div><h1>Exams</h1></div><button class="btn orange" onclick="examForm()">+ New Exam</button></div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Exam</th><th>Questions</th><th>Duration</th><th>Availability</th><th>Status</th><th>Device</th><th>Actions</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${esc(r.title)}</b><div class="small-text muted">${esc(r.description||'')}</div></td><td>${r.question_count}</td><td>${r.duration_minutes} min</td><td><div class="schedule-cell"><b>${r.available_from?esc(fmtSchedule(r.available_from)):'Immediately'}</b><span>${r.expires_at?`Until ${esc(fmtSchedule(r.expires_at))}`:'No expiry'}</span></div></td><td><span class="pill">${r.status}</span></td><td>${Number(r.desktop_required)===1?'<span class="device-badge">Desktop</span>':'<span class="muted small-text">Any device</span>'}</td><td><div class="actions"><button class="btn small ghost" onclick="questionManager(${r.id},'${esc(r.title).replaceAll("'","&#39;")}')">Questions</button><button class="btn small ghost" onclick='examForm(${JSON.stringify(r).replace(/'/g,"&#39;")})'>Edit</button><button class="btn small danger" onclick="deleteExam(${r.id})">Delete</button></div></td></tr>`).join('')||`<tr><td colspan="7" class="empty">No exams.</td></tr>`}</tbody></table></div></div>`}
function attachmentRows(exam){let raw=exam?.attachments||exam?.attachments_json||[];let arr=[];try{arr=Array.isArray(raw)?raw:JSON.parse(raw||'[]')}catch{};if(!arr.length)arr=[{}];return arr.map(attachmentRow).join('')}
function attachmentRow(a={}){return `<div class="attachment-row"><div class="field"><label>File name</label><input name="attachmentName" maxlength="200" placeholder="e.g. Excel template" value="${esc(a?.name||'')}"></div><div class="field"><label>File URL</label><input name="attachmentUrl" type="url" maxlength="2000" placeholder="https://..." value="${esc(a?.url||'')}"></div><button type="button" class="btn small ghost" onclick="this.closest('.attachment-row').remove()">Remove</button></div>`}
function addAttachmentRow(){document.getElementById('attachmentRows')?.insertAdjacentHTML('beforeend',attachmentRow())}
function examForm(exam=null){const startValue=localInputValue(exam?.available_from);const hours=exam?.available_from&&exam?.expires_at?Math.max(1,Math.round((Date.parse(exam.expires_at)-Date.parse(exam.available_from))/3600000)):24;openModal(`<div class="modal-head"><div><div class="eyebrow">${exam?'Edit exam':'Create exam'}</div><h2>${exam?'Update assessment':'New assessment'}</h2></div><button class="icon-btn" onclick="closeModal()">×</button></div><form class="form" onsubmit="saveExam(event,${exam?.id||0})"><div class="field"><label>Title</label><input name="title" required value="${esc(exam?.title||'')}"></div><div class="field"><label>Description</label><textarea name="description" rows="3">${esc(exam?.description||'')}</textarea></div><div class="two-col"><div class="field"><label>Duration (minutes)</label><input name="durationMinutes" type="number" min="1" max="600" required value="${exam?.duration_minutes||30}"></div><div class="field"><label>Passing percentage</label><input name="passingPercentage" type="number" min="0" max="100" step="0.1" required value="${exam?.passing_percentage??50}"></div></div><div class="field"><label>Status</label><select name="status"><option value="active" ${exam?.status==='active'?'selected':''}>Active</option><option value="inactive" ${exam?.status!=='active'?'selected':''}>Inactive</option></select></div><div class="schedule-box"><div class="eyebrow">Exam availability</div><h3>Set when students can access it</h3><div class="two-col"><div class="field"><label>Start date & time</label><input name="availableFrom" type="datetime-local" value="${startValue}"><small class="muted">Leave empty to make it available immediately.</small></div><div class="field"><label>Availability window (hours)</label><input name="availabilityHours" type="number" min="1" max="720" step="1" value="${hours}"><small class="muted">Example: 24 means the exam closes 24 hours after the start time.</small></div></div><div class="schedule-preview" id="schedulePreview"></div></div><label class="switch-field"><input type="checkbox" name="desktopRequired" ${Number(exam?.desktop_required)===1?'checked':''}><span><b>Require desktop / laptop</b><small>Show a warning and prevent this exam from starting on phones and tablets.</small></span></label><div class="card reading-tip"><b>Mobile-friendly reading</b><span>Paste long reading passages directly into the question text. They will wrap naturally and remain comfortable to read on phones.</span></div><button class="btn orange">Save Exam</button></form>`);updateSchedulePreview();const f=document.querySelector('#modal form');f?.querySelector('[name=availableFrom]')?.addEventListener('input',updateSchedulePreview);f?.querySelector('[name=availabilityHours]')?.addEventListener('input',updateSchedulePreview)}
function updateSchedulePreview(){const f=document.querySelector('#modal form');if(!f)return;const start=f.querySelector('[name=availableFrom]')?.value,h=Number(f.querySelector('[name=availabilityHours]')?.value),el=document.getElementById('schedulePreview');if(!el)return;if(!start){el.innerHTML='<b>Availability:</b> Immediately, with no automatic expiry.';return}const d=new Date(start);if(Number.isNaN(d.getTime())||!Number.isFinite(h)||h<1){el.textContent='Enter a valid start date and availability window.';return}const end=new Date(d.getTime()+h*3600000);el.innerHTML=`<b>Starts:</b> ${esc(d.toLocaleString([], {dateStyle:'medium',timeStyle:'short'}))}<br><b>Expires:</b> ${esc(end.toLocaleString([], {dateStyle:'medium',timeStyle:'short'}))}`}
async function saveExam(e,id){e.preventDefault();const fd=new FormData(e.target);const start=fd.get('availableFrom');const hours=fd.get('availabilityHours');const data={title:fd.get('title'),description:fd.get('description'),durationMinutes:fd.get('durationMinutes'),passingPercentage:fd.get('passingPercentage'),status:fd.get('status'),desktopRequired:fd.get('desktopRequired')==='on',availableFrom:start?new Date(start).toISOString():'',availabilityHours:hours};try{await api(id?`/api/admin/exams/${id}`:'/api/admin/exams',{method:id?'PUT':'POST',body:JSON.stringify(data)});closeModal();showToast('Exam saved');adminTab('exams')}catch(x){showToast(x.message)}}
async function deleteExam(id){if(!confirm('Delete this exam and all its questions/results?'))return;try{await api(`/api/admin/exams/${id}`,{method:'DELETE'});showToast('Exam deleted');adminTab('exams')}catch(x){showToast(x.message)}}
async function questionManager(examId,title){const qs=await api(`/api/admin/exams/${examId}/questions`);openModal(`<div class="modal-head"><div><div class="eyebrow">Question bank</div><h2>${esc(title)}</h2><p class="muted">Add questions manually or import up to 200 questions from Excel.</p></div><button class="icon-btn" onclick="closeModal()">×</button></div><div class="actions" style="margin-bottom:15px;flex-wrap:wrap"><button class="btn orange" onclick="questionForm(${examId},null,'${esc(title).replaceAll("'","&#39;")}')">+ Add Question</button><button class="btn ghost" onclick="questionImportForm(${examId},'${esc(title).replaceAll("'","&#39;")}')">Import Excel</button><a class="btn ghost" href="/question-import-template.xlsx" download>Download Template</a></div><div class="stack">${qs.map((q,i)=>{const files=Array.isArray(q.attachments)?q.attachments:[];return `<div class="card"><div class="small-text muted">Question ${i+1} · ${q.points} point${q.points==1?'':'s'} · Correct answer ${q.correct_answer}</div><b>${esc(q.question_text)}</b><p class="small-text muted">A. ${esc(q.option_a)} · B. ${esc(q.option_b)} · C. ${esc(q.option_c)} · D. ${esc(q.option_d)}</p><div class="actions"><button class="btn small ghost" onclick='questionForm(${examId},${JSON.stringify(q).replace(/'/g,"&#39;")},"${esc(title).replaceAll('"','&quot;')}")'>Edit</button><button class="btn small danger" onclick="deleteQuestion(${q.id},${examId},'${esc(title).replaceAll("'","&#39;")}')">Delete</button></div></div>`}).join('')||`<div class="empty">No questions yet.</div>`}</div>`)}
async function loadXLSX(){if(window.XLSX)return window.XLSX;if(window.__xlsxPromise)return window.__xlsxPromise;window.__xlsxPromise=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://cdn.sheetjs.com/xlsx-0.20.3/package/dist/xlsx.full.min.js';script.onload=()=>resolve(window.XLSX);script.onerror=()=>reject(new Error('Could not load the Excel reader. Check your internet connection and try again.'));document.head.appendChild(script)});return window.__xlsxPromise}
function questionImportForm(examId,title){openModal(`<div class="modal-head"><div><div class="eyebrow">Bulk question import</div><h2>Import questions from Excel</h2><p class="muted">Use the template columns: Question, Option A, Option B, Option C, Option D, Correct Answer, Points, Sort Order.</p></div><button class="icon-btn" onclick="questionManager(${examId},'${esc(title).replaceAll("'","&#39;")}')">×</button></div><div class="card import-help"><b>How it works</b><ol class="small-text"><li>Download the template.</li><li>Fill one question per row.</li><li>Save as .xlsx.</li><li>Choose the file below and review the detected rows.</li></ol></div><form class="form" onsubmit="previewQuestionImport(event,${examId},'${esc(title).replaceAll("'","&#39;")}')"><div class="field"><label>Excel file (.xlsx / .xls)</label><input id="questionExcelFile" name="excelFile" type="file" accept=".xlsx,.xls" required></div><button class="btn orange">Read Excel</button></form>`)}
function normalizeExcelHeader(v){return String(v??'').trim().toLowerCase().replace(/[\s_-]+/g,'')}
function excelValue(row,keys){for(const key of keys){const nk=normalizeExcelHeader(key);const found=Object.keys(row).find(k=>normalizeExcelHeader(k)===nk);if(found!==undefined)return row[found]}return ''}
async function previewQuestionImport(e,examId,title){e.preventDefault();const file=e.target.excelFile.files?.[0];if(!file)return;try{const XLSX=await loadXLSX();const data=await file.arrayBuffer();const wb=XLSX.read(data,{type:'array'});const ws=wb.Sheets[wb.SheetNames[0]];const rows=XLSX.utils.sheet_to_json(ws,{defval:'',raw:false});const questions=rows.map((r,i)=>({questionText:String(excelValue(r,['Question','Question Text','question_text'])).trim(),optionA:String(excelValue(r,['Option A','A','option_a'])).trim(),optionB:String(excelValue(r,['Option B','B','option_b'])).trim(),optionC:String(excelValue(r,['Option C','C','option_c'])).trim(),optionD:String(excelValue(r,['Option D','D','option_d'])).trim(),correctAnswer:String(excelValue(r,['Correct Answer','Correct','correct_answer'])).trim().toUpperCase(),points:Number(excelValue(r,['Points','points'])||1),sortOrder:Number(excelValue(r,['Sort Order','Order','sort_order'])||i+1)})).filter(q=>q.questionText||q.optionA||q.optionB||q.optionC||q.optionD);if(!questions.length)throw new Error('No question rows were found in the first sheet.');if(questions.length>200)throw new Error('Maximum 200 questions per import.');const invalid=questions.findIndex(q=>!q.questionText||!q.optionA||!q.optionB||!q.optionC||!q.optionD||!['A','B','C','D'].includes(q.correctAnswer)||!Number.isFinite(q.points)||q.points<=0||!Number.isInteger(q.sortOrder));if(invalid>=0)throw new Error(`Invalid data in imported row ${invalid+2}. Check all required columns and Correct Answer (A/B/C/D).`);openModal(`<div class="modal-head"><div><div class="eyebrow">Import preview</div><h2>${questions.length} questions detected</h2><p class="muted">Review the first few rows, then confirm the import.</p></div><button class="icon-btn" onclick="questionManager(${examId},'${esc(title).replaceAll("'","&#39;")}')">×</button></div><div class="table-wrap"><table class="table"><thead><tr><th>#</th><th>Question</th><th>A</th><th>B</th><th>C</th><th>D</th><th>Correct</th><th>Points</th></tr></thead><tbody>${questions.slice(0,8).map((q,i)=>`<tr><td>${i+1}</td><td>${esc(q.questionText)}</td><td>${esc(q.optionA)}</td><td>${esc(q.optionB)}</td><td>${esc(q.optionC)}</td><td>${esc(q.optionD)}</td><td><b>${q.correctAnswer}</b></td><td>${q.points}</td></tr>`).join('')}</tbody></table></div>${questions.length>8?`<p class="small-text muted">Showing first 8 of ${questions.length} rows.</p>`:''}<div class="actions"><button class="btn ghost" onclick="questionImportForm(${examId},'${esc(title).replaceAll("'","&#39;")}')">Back</button><button class="btn orange" onclick='confirmQuestionImport(${examId},${JSON.stringify(questions).replace(/'/g,"&#39;")},"${esc(title).replaceAll('"','&quot;')}")'>Import ${questions.length} Questions</button></div>`)}catch(x){showToast(x.message||'Unable to read Excel file')}}
async function confirmQuestionImport(examId,questions,title){try{const d=await api('/api/admin/questions/bulk',{method:'POST',body:JSON.stringify({examId,questions})});showToast(`${d.inserted} questions imported`);await questionManager(examId,title)}catch(x){showToast(x.message||'Import failed')}}
function questionAttachmentRows(q){let raw=q?.attachments||q?.attachments_json||[];let arr=[];try{arr=Array.isArray(raw)?raw:JSON.parse(raw||'[]')}catch{};if(!arr.length)arr=[{}];return arr.map(questionAttachmentRow).join('')}
function questionAttachmentRow(a={}){return `<div class="attachment-row question-attachment-row"><div class="field"><label>File name</label><input name="questionAttachmentName" maxlength="200" placeholder="e.g. Case study 1" value="${esc(a?.name||'')}"></div><div class="field"><label>File URL</label><input name="questionAttachmentUrl" type="url" maxlength="2000" placeholder="https://..." value="${esc(a?.url||'')}"></div><button type="button" class="btn small ghost" onclick="this.closest('.question-attachment-row').remove()">Remove</button></div>`}
function addQuestionAttachmentRow(){document.getElementById('questionAttachmentRows')?.insertAdjacentHTML('beforeend',questionAttachmentRow())}
async function questionForm(examId,q,title){let skills=[];try{skills=await api('/api/admin/skills')}catch{}openModal(`<div class="modal-head"><div><div class="eyebrow">${q?'Edit question':'Add question'}</div><h2>${esc(title)}</h2></div><button class="icon-btn" onclick="questionManager(${examId},'${esc(title).replaceAll("'","&#39;")}')">×</button></div><form class="form" onsubmit="saveQuestion(event,${examId},${q?.id||0},'${esc(title).replaceAll("'","&#39;")}')"><div class="field"><label>Question</label><textarea name="questionText" rows="4" required>${esc(q?.question_text||'')}</textarea></div><div class="two-col"><div class="field"><label>Option A</label><input name="optionA" required value="${esc(q?.option_a||'')}"></div><div class="field"><label>Option B</label><input name="optionB" required value="${esc(q?.option_b||'')}"></div><div class="field"><label>Option C</label><input name="optionC" required value="${esc(q?.option_c||'')}"></div><div class="field"><label>Option D</label><input name="optionD" required value="${esc(q?.option_d||'')}"></div></div><div class="two-col"><div class="field"><label>Skill</label><select name="skillId"><option value="">Uncategorized</option>${skills.map(x=>`<option value="${x.id}" ${Number(q?.skill_id)===Number(x.id)?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Topic / sub-skill</label><input name="topic" maxlength="120" placeholder="e.g. Conditionals, Synonyms" value="${esc(q?.topic||'')}"></div></div><div class="two-col"><div class="field"><label>Correct answer</label><select name="correctAnswer">${['A','B','C','D'].map(x=>`<option ${q?.correct_answer===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Points</label><input name="points" type="number" min="0.1" step="0.1" value="${q?.points||1}"></div></div><div class="field"><label>Sort order</label><input name="sortOrder" type="number" value="${q?.sort_order||0}"></div><div class="card reading-tip"><b>Reading passages</b><span>For a reading passage, paste the full text into the question field. The student view is optimized for comfortable reading on phones.</span></div><button class="btn orange">Save Question</button></form>`)}
async function saveQuestion(e,examId,id,title){e.preventDefault();const fd=new FormData(e.target);const data=Object.fromEntries(fd);data.examId=examId;try{await api(id?`/api/admin/questions/${id}`:'/api/admin/questions',{method:id?'PUT':'POST',body:JSON.stringify(data)});await questionManager(examId,title);showToast('Question saved')}catch(x){showToast(x.message)}}
async function deleteQuestion(id,examId,title){if(!confirm('Delete this question?'))return;await api(`/api/admin/questions/${id}`,{method:'DELETE'});await questionManager(examId,title);showToast('Question deleted')}

async function adminResults(el){const rows=await api('/api/admin/results');el.innerHTML=`<div class="dashboard-head"><div><div class="eyebrow">Performance</div><h1>Results</h1></div><div class="toolbar"><input id="resultSearch" placeholder="Search results…" oninput="searchResults()"></div></div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Student</th><th>Exam</th><th>Score</th><th>Percentage</th><th>Status</th><th>Date</th><th></th></tr></thead><tbody id="results-body">${resultRows(rows)}</tbody></table></div></div>`}
function resultRows(rows){return rows.map(r=>`<tr><td><b>${esc(r.student_id)}</b><div class="small-text muted">${esc(r.full_name)}</div></td><td>${esc(r.title)}</td><td>${r.score}/${r.total_points}</td><td>${Number(r.percentage).toFixed(1)}%</td><td><span class="pill ${r.passed?'pass':'fail'}">${r.passed?'Passed':'Not passed'}</span></td><td>${fmtDate(r.created_at)}</td><td><button class="btn small ghost" onclick="resultDetail(${r.id})">View</button></td></tr>`).join('')||`<tr><td colspan="7" class="empty">No results.</td></tr>`}
let resultTimer;async function searchResults(){clearTimeout(resultTimer);resultTimer=setTimeout(async()=>{const q=document.getElementById('resultSearch').value;const rows=await api('/api/admin/results?q='+encodeURIComponent(q));document.getElementById('results-body').innerHTML=resultRows(rows)},250)}
async function resultDetail(id){const d=await api(`/api/admin/results/${id}`);openModal(`<div class="modal-head"><div><div class="eyebrow">Result detail</div><h2>${esc(d.result.title)}</h2><p class="muted">${esc(d.result.student_id)} · ${esc(d.result.full_name)}</p></div><button class="icon-btn" onclick="closeModal()">×</button></div><div class="grid grid-3"><div class="card"><b>Score</b><div class="score" style="font-size:35px">${Number(d.result.percentage).toFixed(1)}%</div></div><div class="card"><b>Points</b><p>${d.result.score} / ${d.result.total_points}</p></div><div class="card"><b>Status</b><p class="${d.result.passed?'success-text':'danger-text'}">${d.result.passed?'Passed':'Not passed'}</p></div></div><div class="stack" style="margin-top:16px">${d.answers.map((a,i)=>`<div class="card"><b>${i+1}. ${esc(a.question_text)}</b><p class="small-text">Selected: ${a.selected_answer||'No answer'} · Correct: ${a.correct_answer} · ${a.is_correct?'Correct':'Incorrect'}</p></div>`).join('')}</div>`)}
async function adminAdmins(el){const rows=await api('/api/admin/admins');el.innerHTML=`<div class="dashboard-head"><div><div class="eyebrow">Access control</div><h1>Admin users</h1></div><button class="btn orange" onclick="adminForm()">+ Add Admin</button></div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Username</th><th>Role</th><th>Status</th><th>Created</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${esc(r.username)}</b></td><td>${esc(r.role)}</td><td><span class="pill">${r.status}</span></td><td>${fmtDate(r.created_at)}</td><td>${r.id!==undefined?`<button class="btn small ghost" onclick="toggleAdmin(${r.id},'${r.status==='active'?'blocked':'active'}')">${r.status==='active'?'Block':'Activate'}</button>`:''}</td></tr>`).join('')}</tbody></table></div></div>`}
function adminForm(){openModal(`<div class="modal-head"><div><div class="eyebrow">Access control</div><h2>Add admin</h2></div><button class="icon-btn" onclick="closeModal()">×</button></div><form class="form" onsubmit="saveAdmin(event)"><div class="field"><label>Username</label><input name="username" pattern="[A-Za-z0-9._\-]{3,80}" required></div><div class="field"><label>Password</label><input name="password" type="password" minlength="8" required></div><div class="field"><label>Role</label><select name="role"><option value="admin">Admin</option><option value="super_admin">Super admin</option></select></div><button class="btn orange">Create Admin</button></form>`)}
async function saveAdmin(e){e.preventDefault();try{await api('/api/admin/admins',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();showToast('Admin created');adminTab('admins')}catch(x){showToast(x.message)}}
async function toggleAdmin(id,status){await api(`/api/admin/admins/${id}`,{method:'PATCH',body:JSON.stringify({status})});showToast('Admin status updated');adminTab('admins')}
function openModal(html){const d=document.createElement('div');d.id='modal';d.className='modal-backdrop';d.innerHTML=`<div class="modal">${html}</div>`;document.body.appendChild(d)}function closeModal(){document.getElementById('modal')?.remove()}
function toggleLang(){state.lang=state.lang==='en'?'ar':'en';localStorage.setItem('exam_lang',state.lang);document.documentElement.lang=state.lang;document.documentElement.dir=state.lang==='ar'?'rtl':'ltr';render();requestAnimationFrame(translateUI)}
function toggleTheme(){state.theme=state.theme==='dark'?'light':'dark';localStorage.setItem('exam_theme',state.theme);applyTheme();render()}
function applyTheme(){document.body.classList.toggle('dark-mode',state.theme==='dark');document.documentElement.lang=state.lang;document.documentElement.dir=state.lang==='ar'?'rtl':'ltr'}
function go(v){if(v==='admin-login'){location.href='/admin';return}if(v==='home'){if(location.pathname!=='/admin.html'&&location.pathname!=='/admin')state.view='home';else state.adminTab='overview'}else if(v==='results'){state.view=state.me?.user?'dashboard':'login'}else if(v==='dashboard'&&!state.me?.user){state.view='login'}else state.view=v;if(v!=='exam')clearInterval(state.timer);render()}
window.go=go;window.answerQuestion=answerQuestion;window.nextQuestion=nextQuestion;window.previousQuestion=previousQuestion;window.jumpToQuestion=jumpToQuestion;window.toggleLang=toggleLang;window.toggleTheme=toggleTheme;window.adminLogin=adminLogin;window.studentLogin=studentLogin;window.studentRegister=studentRegister;window.studentForm=studentForm;window.saveStudent=saveStudent;window.groupForm=groupForm;window.saveGroup=saveGroup;window.logout=logout;window.startExam=startExam;window.submitExam=submitExam;window.adminTab=adminTab;window.searchStudents=searchStudents;window.studentDetail=studentDetail;window.toggleStudent=toggleStudent;window.examForm=examForm;window.addAttachmentRow=addAttachmentRow;window.addQuestionAttachmentRow=addQuestionAttachmentRow;window.saveExam=saveExam;window.deleteExam=deleteExam;window.questionManager=questionManager;window.questionImportForm=questionImportForm;window.previewQuestionImport=previewQuestionImport;window.confirmQuestionImport=confirmQuestionImport;window.questionForm=questionForm;window.saveQuestion=saveQuestion;window.deleteQuestion=deleteQuestion;window.searchResults=searchResults;window.resultDetail=resultDetail;window.adminForm=adminForm;window.saveAdmin=saveAdmin;window.toggleAdmin=toggleAdmin;window.closeModal=closeModal;
boot();
